//! The custom controls, driven through window events on Slint's testing
//! backend. No window shows and no event loop runs.

#![allow(clippy::unwrap_used, clippy::expect_used, reason = "a test asserts by panicking")]

use i_slint_backend_testing::{AccessibleRole, ElementHandle};
use slint::platform::{Key, PointerEventButton, WindowEvent};
use slint::{ComponentHandle, LogicalPosition, SharedString};

mod ui {
    #![allow(unreachable_pub, reason = "generated by slint")]
    #![allow(missing_debug_implementations, reason = "generated by slint")]
    #![allow(missing_docs, reason = "generated by slint")]
    #![allow(clippy::unwrap_used, reason = "generated by slint")]
    slint::slint! {
        import { Icons } from "../ui/icons.slint";
        import { IconButton, ThemedButton, ThemedCheck, ThemedEdit } from "../ui/controls.slint";
        import { Shell } from "../ui/shell.slint";
        import { Theme, ThemeId } from "../ui/theme.slint";

        export { Theme, ThemeId }

        export component Harness inherits Window {
            width: 400px;
            height: 400px;
            in-out property <int> clicks;
            in-out property <int> off-clicks;
            in-out property <int> accepts;
            in-out property <int> escapes;
        in-out property <int> screen-escapes;
            in-out property <int> toggles;
            in-out property <int> icon-clicks;
            in-out property <int> shell-clicks;
            in-out property <int> theme-clicks;
            in-out property <bool> escape-handled: true;
            in-out property <bool> checked;
            in-out property <bool> locked-checked;
            in-out property <string> typed <=> edit.text;
            out property <bool> first-focus: first.has-focus;
            out property <bool> off-focus: off.has-focus;
            out property <bool> edit-focus: edit.has-focus;
            out property <bool> check-focus: check.has-focus;
        out property <bool> locked-edit-focus: locked-edit.has-focus;
        out property <string> locked-text <=> locked-edit.text;

            public function focus-first() { first.focus(); }
            public function focus-off() { off.focus(); }
            public function focus-edit() { edit.focus(); }
            public function focus-check() { check.focus(); }
            public function focus-locked() { locked.focus(); }
        public function focus-locked-edit() { locked-edit.focus(); }

            first := ThemedButton {
                x: 10px; y: 10px; width: 160px; height: 30px;
                text: "First";
                clicked => { root.clicks += 1; }
            }
            off := ThemedButton {
                x: 10px; y: 50px; width: 160px; height: 30px;
                text: "Off";
                enabled: false;
                clicked => { root.off-clicks += 1; }
            }
            // The screen behind the edit: it sees only the keys the edit leaves unhandled.
            FocusScope {
                x: 0px; y: 90px; width: 400px; height: 30px;
                enabled: false;
                key-pressed(event) => {
                    if event.text == Key.Escape {
                        root.screen-escapes += 1;
                        return accept;
                    }
                    return reject;
                }
                edit := ThemedEdit {
                    x: 10px; width: 160px; height: 30px;
                    label: "Name";
                    accepted => { root.accepts += 1; }
                    escaped => { root.escapes += 1; return root.escape-handled; }
                }
            }
            check := ThemedCheck {
                x: 10px; y: 130px; width: 160px; height: 30px;
                text: "Option";
                checked <=> root.checked;
                toggled => { root.toggles += 1; }
            }
            locked := ThemedCheck {
                x: 10px; y: 170px; width: 160px; height: 30px;
                text: "Locked option";
                enabled: false;
                checked <=> root.locked-checked;
            }
            icon := IconButton {
                x: 10px; y: 210px; width: 30px; height: 30px;
                label: "Close it";
                icon: Icons.close;
                clicked => { root.icon-clicks += 1; }
            }
            shell-button := ThemedButton {
                x: 10px; y: 250px; width: 160px; height: 30px;
                text: "Shell look";
                look: Shell.look;
                clicked => { root.shell-clicks += 1; }
            }
            locked-edit := ThemedEdit {
                x: 10px; y: 330px; width: 160px; height: 30px;
                text: "fixed";
                enabled: false;
                accepted => { root.accepts += 1; }
            }
            theme-button := ThemedButton {
                x: 10px; y: 290px; width: 160px; height: 30px;
                text: "Theme look";
                clicked => { root.theme-clicks += 1; }
            }
        }
    }
}

use ui::{Harness, Theme, ThemeId};

fn harness() -> Harness {
    i_slint_backend_testing::init_no_event_loop();
    Harness::new().unwrap()
}

fn press(ui: &Harness, text: impl Into<SharedString>) {
    let text = text.into();
    ui.window().dispatch_event(WindowEvent::KeyPressed { text: text.clone() });
    ui.window().dispatch_event(WindowEvent::KeyReleased { text });
}

fn key(ui: &Harness, key: Key) {
    press(ui, SharedString::from(key));
}

fn click_at(ui: &Harness, down: (f32, f32), up: (f32, f32)) {
    let button = PointerEventButton::Left;
    ui.window().dispatch_event(WindowEvent::PointerMoved {
        position: LogicalPosition::new(down.0, down.1),
    });
    ui.window().dispatch_event(WindowEvent::PointerPressed {
        position: LogicalPosition::new(down.0, down.1),
        button,
    });
    ui.window().dispatch_event(WindowEvent::PointerMoved {
        position: LogicalPosition::new(up.0, up.1),
    });
    ui.window().dispatch_event(WindowEvent::PointerReleased {
        position: LogicalPosition::new(up.0, up.1),
        button,
    });
}

fn click(ui: &Harness, x: f32, y: f32) {
    click_at(ui, (x, y), (x, y));
}

fn by_label(ui: &Harness, label: &str) -> ElementHandle {
    ElementHandle::find_by_accessible_label(ui, label)
        .next()
        .unwrap_or_else(|| panic!("no element is labelled {label}"))
}

#[test]
fn a_button_activates_on_enter_and_space() {
    let ui = harness();
    ui.invoke_focus_first();
    assert!(ui.get_first_focus());
    key(&ui, Key::Return);
    assert_eq!(ui.get_clicks(), 1);
    press(&ui, " ");
    assert_eq!(ui.get_clicks(), 2);
    press(&ui, "a");
    key(&ui, Key::Escape);
    assert_eq!(ui.get_clicks(), 2);
}

#[test]
fn a_click_activates_once_on_release() {
    let ui = harness();
    click(&ui, 20.0, 20.0);
    assert_eq!(ui.get_clicks(), 1);
    click_at(&ui, (20.0, 20.0), (300.0, 300.0));
    assert_eq!(ui.get_clicks(), 1, "a release outside is no click");
}

#[test]
fn a_click_gives_the_button_the_focus() {
    let ui = harness();
    click(&ui, 20.0, 20.0);
    assert!(ui.get_first_focus());
}

#[test]
fn a_disabled_button_ignores_keys_and_pointer() {
    let ui = harness();
    ui.invoke_focus_off();
    assert!(!ui.get_off_focus());
    key(&ui, Key::Return);
    press(&ui, " ");
    click(&ui, 20.0, 60.0);
    assert_eq!(ui.get_off_clicks(), 0);
    assert!(!ui.get_off_focus());
}

#[test]
fn tab_moves_focus_in_source_order_and_skips_disabled_controls() {
    let ui = harness();
    ui.invoke_focus_first();
    key(&ui, Key::Tab);
    assert!(ui.get_edit_focus(), "the disabled button is skipped");
    key(&ui, Key::Tab);
    assert!(ui.get_check_focus());
    ui.window().dispatch_event(WindowEvent::KeyPressed { text: Key::Shift.into() });
    key(&ui, Key::Tab);
    assert!(ui.get_edit_focus());
    key(&ui, Key::Tab);
    assert!(ui.get_first_focus());
    ui.window().dispatch_event(WindowEvent::KeyReleased { text: Key::Shift.into() });
}

#[test]
fn an_edit_takes_typing_and_enter_accepts() {
    let ui = harness();
    ui.invoke_focus_edit();
    press(&ui, "1");
    press(&ui, "2");
    assert_eq!(ui.get_typed(), "12");
    assert_eq!(ui.get_accepts(), 0);
    key(&ui, Key::Return);
    assert_eq!(ui.get_typed(), "12");
    assert_eq!(ui.get_accepts(), 1);
}

#[test]
fn escape_reaches_the_owner_of_the_edit() {
    let ui = harness();
    ui.invoke_focus_edit();
    key(&ui, Key::Escape);
    assert_eq!(ui.get_escapes(), 1);
    assert_eq!(ui.get_screen_escapes(), 0, "a handled Escape stops at the edit");
}

#[test]
fn an_edit_passes_escape_on_when_its_owner_declines() {
    let ui = harness();
    ui.set_escape_handled(false);
    ui.invoke_focus_edit();
    key(&ui, Key::Escape);
    assert_eq!(ui.get_escapes(), 1);
    assert_eq!(ui.get_screen_escapes(), 1, "the screen behind sees the key");
    assert!(ui.get_edit_focus(), "an unhandled Escape does not drop the focus");
}

#[test]
fn a_disabled_edit_takes_no_focus_and_no_typing() {
    let ui = harness();
    ui.invoke_focus_locked_edit();
    click(&ui, 20.0, 340.0);
    press(&ui, "x");
    key(&ui, Key::Return);
    assert!(!ui.get_locked_edit_focus());
    assert_eq!(ui.get_locked_text(), "fixed");
    assert_eq!(ui.get_accepts(), 0);
}

#[test]
fn a_check_toggles_on_space_and_click() {
    let ui = harness();
    ui.invoke_focus_check();
    press(&ui, " ");
    assert!(ui.get_checked());
    click(&ui, 20.0, 140.0);
    assert!(!ui.get_checked());
    key(&ui, Key::Return);
    assert!(ui.get_checked());
    assert_eq!(ui.get_toggles(), 3);
}

#[test]
fn a_disabled_check_does_not_toggle() {
    let ui = harness();
    ui.invoke_focus_locked();
    press(&ui, " ");
    click(&ui, 20.0, 180.0);
    assert!(!ui.get_locked_checked());
}

#[test]
fn the_controls_set_their_accessibility_properties() {
    let ui = harness();
    let button = by_label(&ui, "First");
    assert_eq!(button.accessible_role(), Some(AccessibleRole::Button));
    assert_eq!(button.accessible_enabled(), Some(true));
    assert_eq!(by_label(&ui, "Off").accessible_enabled(), Some(false));

    let edit = by_label(&ui, "Name");
    assert_eq!(edit.accessible_role(), Some(AccessibleRole::TextInput));
    ui.invoke_focus_edit();
    press(&ui, "7");
    assert_eq!(edit.accessible_value().as_deref(), Some("7"));

    let check = by_label(&ui, "Option");
    assert_eq!(check.accessible_role(), Some(AccessibleRole::Checkbox));
    assert_eq!(check.accessible_checked(), Some(false));
    ui.set_checked(true);
    assert_eq!(check.accessible_checked(), Some(true));

    let icon = by_label(&ui, "Close it");
    assert_eq!(icon.accessible_role(), Some(AccessibleRole::Button));
}

#[test]
fn the_default_accessible_action_activates() {
    let ui = harness();
    by_label(&ui, "First").invoke_accessible_default_action();
    by_label(&ui, "Close it").invoke_accessible_default_action();
    by_label(&ui, "Option").invoke_accessible_default_action();
    assert_eq!((ui.get_clicks(), ui.get_icon_clicks()), (1, 1));
    assert!(ui.get_checked());
}

#[test]
fn a_shell_look_and_a_theme_look_both_build() {
    let ui = harness();
    click(&ui, 20.0, 260.0);
    click(&ui, 20.0, 300.0);
    assert_eq!((ui.get_shell_clicks(), ui.get_theme_clicks()), (1, 1));
    ui.global::<Theme>().set_id(ThemeId::Pr);
    click(&ui, 20.0, 300.0);
    assert_eq!(ui.get_theme_clicks(), 2);
}
